INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '食品加工業（冷凍食品を除く）', '2024年における食品加工業の従業者一人あたりの現金給与額は、およそいくらか。最も近いものを選びなさい。', '[{"headers":["年次","事業所数","従業者数（人）","現金給与総額（百万円）","付加価値額（百万円）"],"rows":[["2022","2,850","45,800","168,200","285,400"],["2023","2,790","43,500","160,500","270,800"],["2024","2,705","41,250","152,400","258,900"]]}]', '["3.69万円","36.9万円","270,669円","3,694,545円","いずれでもない"]', 3, '["現金給与総額を従業者数で割って求める。2024年の現金給与総額は152,400（百万円）＝152,400,000,000円、従業者数は41,250人である。\n152,400,000,000÷41,250＝およそ3,694,545円となる。よって選択肢Dが正解。分子と分母を取り違えると選択肢Cのような値になるため注意。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '電子部品製造業', '2024年における電子部品製造業の、事業所1カ所あたりの付加価値額は、およそいくらか。最も近いものを選びなさい。', '[{"headers":["年次","事業所数","従業者数（人）","現金給与総額（百万円）","付加価値額（百万円）"],"rows":[["2022","1,920","38,500","142,000","198,700"],["2023","1,875","37,200","138,500","205,300"],["2024","1,840","36,100","133,800","215,600"]]}]', '["11.7百万円","58.6百万円","117.2百万円","1,172百万円","いずれでもない"]', 2, '["付加価値額を事業所数で割って求める。2024年の付加価値額は215,600（百万円）、事業所数は1,840である。\n215,600÷1,840＝およそ117.2（百万円）となる。よって選択肢Cが正解。桁を一つ間違えると選択肢AやDのような値になる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'IT関連サービス業', '2024年におけるIT関連サービス業の従業者一人あたりの付加価値額は、およそいくらか。最も近いものを選びなさい。', '[{"headers":["年次","事業所数","従業者数（人）","現金給与総額（百万円）","付加価値額（百万円）"],"rows":[["2022","980","14,200","98,500","165,300"],["2023","1,015","14,750","103,200","178,900"],["2024","1,050","15,230","108,700","189,500"]]}]', '["8.0万円","80,369円","124.4万円","12,442,548円","いずれでもない"]', 3, '["付加価値額を従業者数で割って求める。2024年の付加価値額は189,500（百万円）＝189,500,000,000円、従業者数は15,230人である。\n189,500,000,000÷15,230＝およそ12,442,548円となる。よって選択肢Dが正解。分母と分子を逆にすると選択肢Bのような値になってしまう点に注意。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'スマートフォンのセキュリティに関する不安（国別）', '日本とドイツにおいて、「とても不安を感じる」または「やや不安を感じる」と回答した人の合計割合を比較したとき、その差はいくらか。最も近いものを選びなさい。', '[{"headers":["","とても不安を感じる","やや不安を感じる","あまり不安を感じない","全く不安を感じない","よくわからない"],"rows":[["日本","22.5%","34.8%","25.1%","9.6%","8.0%"],["ドイツ","19.3%","41.2%","27.5%","7.0%","5.0%"]]}]', '["2.8%","3.0%","3.2%","3.4%","3.6%"]', 2, '["日本の合計は22.5＋34.8＝57.3（％）。ドイツの合計は19.3＋41.2＝60.5（％）。\n差は60.5－57.3＝3.2（％）となる。よって選択肢Cが正解。単項目でなく2項目の和を先に求める必要がある点に注意。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'テレワークの満足度（国別）', '日本と米国において、「とても満足」または「やや満足」と回答した人の合計割合を比較したとき、米国は日本より何ポイント高いか。最も近いものを選びなさい。', '[{"headers":["","とても満足","やや満足","どちらともいえない","やや不満","とても不満"],"rows":[["日本","15.6%","29.4%","31.0%","15.0%","9.0%"],["米国","28.2%","33.1%","22.7%","10.0%","6.0%"]]}]', '["14.5pt","15.3pt","16.3pt","17.1pt","18.0pt"]', 2, '["日本の合計は15.6＋29.4＝45.0（％）。米国の合計は28.2＋33.1＝61.3（％）。\n差は61.3－45.0＝16.3（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '食品ロス問題への関心度（国別）', '日本と英国において、「あまり関心がない」または「全く関心がない」と回答した人の合計割合を比較したとき、その差はいくらか。最も近いものを選びなさい。', '[{"headers":["","非常に関心がある","やや関心がある","どちらともいえない","あまり関心がない","全く関心がない"],"rows":[["日本","12.0%","22.5%","30.5%","20.0%","15.0%"],["英国","8.5%","18.0%","28.5%","25.0%","20.0%"]]}]', '["8.0%","9.0%","10.0%","11.0%","12.0%"]', 2, '["日本の合計は20.0＋15.0＝35.0（％）。英国の合計は25.0＋20.0＝45.0（％）。\n差は45.0－35.0＝10.0（％）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '地域別輸出額構成比の推移', '2005年の全体の輸出額をMとおくとき、アジアとその他を合わせた輸出額を表す式として正しいものを選びなさい。', '[{"headers":["","先進国","アジア","中東","中南米","その他"],"rows":[["1985年","45%","20%","10%","15%","10%"],["1995年","40%","25%","10%","10%","15%"],["2005年","30%","35%","8%","12%","15%"]]}]', '["M/4","M/3","M/2","3M/5","2M/3"]', 2, '["2005年のアジアは35％、その他は15％なので、合計は35＋15＝50（％）。\n全体をMとすると、50：100＝N：Mより N＝50M/100＝M/2 となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9001);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '地域別輸出額構成比の推移', '1985年の中東への輸出額をQとおくとき、1985年における全体の輸出額を表す式として正しいものを選びなさい。', '[{"headers":["","先進国","アジア","中東","中南米","その他"],"rows":[["1985年","45%","20%","10%","15%","10%"],["1995年","40%","25%","10%","10%","15%"],["2005年","30%","35%","8%","12%","15%"]]}]', '["5Q","8Q","10Q","12Q","15Q"]', 2, '["1985年の中東の割合は10％である。全体をWとすると、W：Q＝100：10 という比の関係が成り立つ。\nこれを解くと10W＝100Qとなり、W＝10Qと導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9001);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '一次エネルギー消費内訳の推移', '2020年の全体のエネルギー消費量をMとおくとき、天然ガスと再生可能エネルギーを合わせた消費量を表す式として正しいものを選びなさい。', '[{"headers":["","石油","石炭","天然ガス","原子力","再生可能エネルギー"],"rows":[["2000年","40%","25%","15%","10%","10%"],["2010年","35%","20%","20%","15%","10%"],["2020年","25%","10%","25%","10%","30%"]]}]', '["M/2","9M/20","11M/20","3M/5","7M/10"]', 2, '["2020年の天然ガスは25％、再生可能エネルギーは30％なので、合計は25＋30＝55（％）。\n全体をMとすると、55／100＝11／20 なので、求める式は11M/20となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9002);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '一次エネルギー消費内訳の推移', '2000年の石炭の消費量をPとおくとき、2000年における全体のエネルギー消費量を表す式として正しいものを選びなさい。', '[{"headers":["","石油","石炭","天然ガス","原子力","再生可能エネルギー"],"rows":[["2000年","40%","25%","15%","10%","10%"],["2010年","35%","20%","20%","15%","10%"],["2020年","25%","10%","25%","10%","30%"]]}]', '["5P/2","3P","4P","5P","25P/4"]', 2, '["2000年の石炭の割合は25％である。全体をWとすると、W：P＝100：25 という比の関係が成り立つ。\nこれを解くと25W＝100Pとなり、W＝4Pと導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9002);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別売上（4月〜6月）', '4つの支店のうち、4月から6月にかけての売上の増加率が最も大きい支店を一つ選びなさい。', '[{"headers":["支店名","4月売上","5月売上","6月売上","3カ月合計","平均売上"],"rows":[["P支店","1,200","1,250","1,300","3,750","1,250.0"],["Q支店","900","1,000","1,080","2,980","993.3"],["R支店","1,500","1,450","1,550","4,500","1,500.0"],["S支店","300","600","750","1,650","550.0"]]}]', '["P支店","Q支店","R支店","S支店","すべて同じ"]', 3, '["各支店の増加率を計算する。P支店は1,300/1,200＝約1.08倍、Q支店は1,080/900＝1.20倍、R支店は1,550/1,500＝約1.03倍、S支店は750/300＝2.50倍である。\nS支店は4月時点の売上が小さいため、増加率で見ると他の支店を大きく上回る。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9003);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.10倍を超えている支店はいくつあるか。', '[{"headers":["支店名","4月売上","5月売上","6月売上","3カ月合計","平均売上"],"rows":[["P支店","1,200","1,250","1,300","3,750","1,250.0"],["Q支店","900","1,000","1,080","2,980","993.3"],["R支店","1,500","1,450","1,550","4,500","1,500.0"],["S支店","300","600","750","1,650","550.0"]]}]', '["なし","1つ","2つ","3つ","4つ"]', 2, '["各支店について「4月売上×1.10」と平均売上を比較する。\nP支店：4月1,200×1.10＝1,320に対し平均は1,250.0で下回る。\nQ支店：4月900×1.10＝990に対し平均は993.3で上回る。\nR支店：4月1,500×1.10＝1,650に対し平均は1,500.0で下回る。\nS支店：4月300×1.10＝330に対し平均は550.0で大きく上回る。\n条件を満たすのはQ支店とS支店の2つ。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9003);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別売上（4月〜6月）', '4つの支店のうち、4月から6月にかけての売上の増加率が最も大きい支店を一つ選びなさい。', '[{"headers":["支店名","4月売上","5月売上","6月売上","3カ月合計","平均売上"],"rows":[["K支店","2,000","2,100","2,200","6,300","2,100.0"],["L支店","1,600","1,750","1,900","5,250","1,750.0"],["M支店","800","850","900","2,550","850.0"],["N支店","500","900","1,100","2,500","833.3"]]}]', '["K支店","L支店","M支店","N支店","すべて同じ"]', 3, '["各支店の増加率を計算する。K支店は2,200/2,000＝1.10倍、L支店は1,900/1,600＝約1.19倍、M支店は900/800＝1.125倍、N支店は1,100/500＝2.20倍である。\nN支店は4月時点の売上が特に小さいため、増加率が突出して大きくなる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9004);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.30倍を超えている支店はいくつあるか。', '[{"headers":["支店名","4月売上","5月売上","6月売上","3カ月合計","平均売上"],"rows":[["K支店","2,000","2,100","2,200","6,300","2,100.0"],["L支店","1,600","1,750","1,900","5,250","1,750.0"],["M支店","800","850","900","2,550","850.0"],["N支店","500","900","1,100","2,500","833.3"]]}]', '["なし","1つ","2つ","3つ","4つ"]', 1, '["各支店について「4月売上×1.30」と平均売上を比較する。\nK支店：2,000×1.30＝2,600に対し平均は2,100.0で下回る。\nL支店：1,600×1.30＝2,080に対し平均は1,750.0で下回る。\nM支店：800×1.30＝1,040に対し平均は850.0で下回る。\nN支店：500×1.30＝650に対し平均は833.3で上回る。\n条件を満たすのはN支店のみで1つ。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9004);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '農産物生産量（トン）', '2024年における野菜の生産量は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers":["年","米","野菜","果物","その他","合計"],"rows":[["2022年","3,200","2,850","1,200","450","7,700"],["2023年","3,100","3,050","1,250","470","7,870"],["2024年","3,000","3,300","1,300","500","8,100"]]}]', '["12.3%","14.0%","15.8%","17.5%","19.2%"]', 2, '["2022年の野菜は2,850トン、2024年は3,300トンである。増加率は（3,300－2,850）÷2,850＝450÷2,850＝約0.158となる。\n百分率に直すと約15.8％となるため、選択肢Cが最も近い。分母を2024年の数値にしないよう注意する。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '地域別人口（千人）', '2030年における都市部の人口は、2010年と比較して約何%増加すると予測されているか。最も近いものを選びなさい。', '[{"headers":["年","都市部","郊外","農村部","合計"],"rows":[["2010年","5,200","3,100","2,200","10,500"],["2020年","5,800","3,300","2,000","11,100"],["2030年（予測）","6,500","3,500","1,800","11,800"]]}]', '["20.0%","22.5%","25.0%","27.5%","30.0%"]', 2, '["2010年の都市部人口は5,200千人、2030年は6,500千人である。増加率は（6,500－5,200）÷5,200＝1,300÷5,200＝0.25となる。\n百分率に直すと25.0％となるため、選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '業種別ITシステム導入件数（件）', '2023年における金融業の導入件数は、2021年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers":["年","製造業","金融業","小売業","その他","合計"],"rows":[["2021年","1,200","800","600","300","2,900"],["2022年","1,350","950","680","320","3,300"],["2023年","1,500","1,150","750","350","3,750"]]}]', '["35.0%","38.5%","41.0%","43.8%","46.5%"]', 3, '["2021年の金融業は800件、2023年は1,150件である。増加率は（1,150－800）÷800＝350÷800＝0.4375となる。\n百分率に直すと約43.8％となるため、選択肢Dが最も近い。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '部門別平均年収と人数', '3部門を合わせた全社員の平均年収はいくらか。最も近いものを選びなさい。', '[{"headers":["部門","平均年収（万円）","人数（人）"],"rows":[["営業部","450","30"],["技術部","520","45"],["管理部","480","25"]]}]', '["475万円","483万円","489万円","495万円","500万円"]', 2, '["単純に3つの平均年収を足して3で割るのではなく、部門ごとの人数で重みづけした加重平均を求める必要がある。\n（450×30＋520×45＋480×25）÷（30＋45＋25）＝（13,500＋23,400＋12,000）÷100＝48,900÷100＝489（万円）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '商品別売上構成比', '全体の売上高をSとおくとき、A商品とC商品を合わせた売上高を表す式として正しいものを選びなさい。', '[{"headers":["商品","構成比"],"rows":[["A商品","30%"],["B商品","45%"],["C商品","25%"]]}]', '["S/2","9S/20","11S/20","3S/5","3S/4"]', 2, '["A商品とC商品の構成比の合計は30＋25＝55（％）。\n全体をSとすると、55／100＝11／20 なので、求める式は11S/20となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別年間売上（万円）', 'E支店とF支店の2021年から2023年までの3年間の売上合計を比較したとき、E支店の合計はF支店の合計のおよそ何倍か。最も近いものを選びなさい。', '[{"headers":["","2021年","2022年","2023年","3年合計"],"rows":[["E支店","1,800","2,000","2,200","6,000"],["F支店","1,200","1,400","1,600","4,200"]]}]', '["1.20倍","1.33倍","1.43倍","1.50倍","1.60倍"]', 2, '["E支店の3年合計は6,000万円、F支店の3年合計は4,200万円である。\n6,000÷4,200＝約1.43となる。よって選択肢Cが最も近い。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
